57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
69	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
70	     * address shape rather than full RFC 5322 conformance.
71	     */
72	    private static final Pattern EMAIL_PATTERN =
73	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
74	
75	    /**
76	     * Common street-type abbreviations expanded during address normalization. Keys and values are
77	     * upper-cased so the mapping is applied after the address has been upper-cased.
78	     */
79	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
80	        "ST", "STREET",
81	        "RD", "ROAD",
82	        "AVE", "AVENUE");
83	
84	    /**
85	     * Maximum number of owners permitted in a single city. Once a city already contains this many
86	     * owners, creating another owner in that city is rejected as a conflict.
87	     */
88	    private static final int CITY_CAPACITY = 50;
89	
90	    private final ClinicService clinicService;
91	
92	    private final OwnerMapper ownerMapper;
93	
94	    private final PetMapper petMapper;
95	
96	    private final VisitMapper visitMapper;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
111	        Collection<Owner> owners;
112	        if (lastName != null) {
113	            owners = this.clinicService.findOwnerByLastName(lastName);
114	        } else {
115	            owners = this.clinicService.findAllOwners();
116	        }
117	        if (owners.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
126	        Owner owner = this.clinicService.findOwnerById(ownerId);
127	        if (owner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
131	    }
132	
133	    /**
134	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
135	     * upper-cases the value, and expands common street-type abbreviations word-by-word
136	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
137	     * normalizes to the empty string. The normalized value is what the application stores, returns
138	     * and compares for household detection.
139	     *
140	     * @param address the raw address value from the request, may be {@code null}
141	     * @return the normalized address, or the empty string when none was supplied
142	     */
143	    private String normalizeAddress(String address) {
144	        if (address == null) {
145	            return "";
146	        }
147	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
148	        if (collapsed.isEmpty()) {
149	            return "";
150	        }
151	        String[] tokens = collapsed.split(" ");
152	        StringBuilder normalized = new StringBuilder();
153	        for (int i = 0; i < tokens.length; i++) {
154	            if (i > 0) {
155	                normalized.append(' ');
156	            }
157	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
158	        }
159	        return normalized.toString();
160	    }
161	
162	    /**
163	     * Rejects an owner payload that is missing or blank in any required field. The response body's
164	     * {@code errors} array lists the name of each offending field.
165	     *
166	     * @param ownerFieldsDto the owner payload to validate
167	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
168	     */
169	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
170	        List<String> missingFields = new ArrayList<>();
171	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
172	            missingFields.add("firstName");
173	        }
174	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
175	            missingFields.add("lastName");
176	        }
177	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
178	            missingFields.add("address");
179	        }
180	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
181	            missingFields.add("city");
182	        }
183	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
184	            missingFields.add("telephone");
185	        }
186	        if (!missingFields.isEmpty()) {
187	            throw new RequiredFieldsMissingException(missingFields);
188	        }
189	    }
190	
191	    /**
192	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
193	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
194	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
195	     * followed by 8 to 15 digits.
196	     *
197	     * @param telephone the raw telephone value from the request
198	     * @return the E.164 telephone (e.g. {@code +61412345678})
199	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
200	     */
201	    private String normalizeTelephone(String telephone) {
202	        if (telephone == null) {
203	            throw new InvalidFieldsException(List.of("telephone"));
204	        }
205	        String trimmed = telephone.trim();
206	        boolean international = trimmed.startsWith("+");
207	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
208	        String digits;
209	        if (international) {
210	            digits = cleaned.substring(1);
211	        } else {
212	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
213	            digits = "61" + national;
214	        }
215	        if (!digits.matches("[0-9]{8,15}")) {
216	            throw new InvalidFieldsException(List.of("telephone"));
217	        }
218	        return "+" + digits;
219	    }
220	
221	    /**
222	     * Best-effort normalization of an existing owner's stored telephone into E.164 form for
223	     * duplicate comparison, returning {@code null} when the value cannot form valid E.164.
224	     *
225	     * @param telephone an existing stored telephone value, may be {@code null}
226	     * @return the E.164 form, or {@code null} when it cannot be normalized
227	     */
228	    private String toE164OrNull(String telephone) {
229	        if (telephone == null) {
230	            return null;
231	        }
232	        try {
233	            return normalizeTelephone(telephone);
234	        }
235	        catch (InvalidFieldsException ex) {
236	            return null;
237	        }
238	    }
239	
240	    /**
241	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
242	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
243	     * be a syntactically valid address; the accepted value is returned lower-cased.
244	     *
245	     * @param email the raw email value from the request, may be {@code null}
246	     * @return the lower-cased email, or {@code null} when none was supplied
247	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
248	     */
249	    private String normalizeEmail(String email) {
250	        if (email == null || email.isBlank()) {
251	            return null;
252	        }
253	        String trimmed = email.trim();
254	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
255	            throw new InvalidFieldsException(List.of("email"));
256	        }
257	        return trimmed.toLowerCase(Locale.ROOT);
258	    }
259	
260	    /**
261	     * Rejects a telephone that, once normalized, is already used by any existing owner. Existing
262	     * owners' telephones are normalized the same way before comparison so differently-formatted
263	     * values representing the same number are treated as duplicates.
264	     *
265	     * @param telephone the normalized (E.164) telephone of the owner being created
266	     * @throws DuplicateOwnerTelephoneException if another owner already uses the telephone
267	     */
268	    private void requireUniqueTelephone(String telephone) {
269	        boolean taken = this.clinicService.findAllOwners().stream()
270	            .map(Owner::getTelephone)
271	            .map(this::toE164OrNull)
272	            .filter(existing -> existing != null)
273	            .anyMatch(telephone::equals);
274	        if (taken) {
275	            throw new DuplicateOwnerTelephoneException(telephone);
276	        }
277	    }
278	
279	    /**
280	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
281	     * fields (last name, address) can be compared case-insensitively with collapsed whitespace. A
282	     * {@code null} value normalizes to the empty string.
283	     *
284	     * @param value the raw field value, may be {@code null}
285	     * @return the trimmed, whitespace-collapsed, lower-cased form
286	     */
287	    private String normalizeHousehold(String value) {
288	        if (value == null) {
289	            return "";
290	        }
291	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
292	    }
293	
294	    /**
295	     * Rejects an owner whose last name and address already match another owner (compared
296	     * case-insensitively with collapsed whitespace) - i.e. they would share a household - unless the
297	     * request opts in via {@code sharesHousehold}. Existing owners' fields are normalized the same
298	     * way before comparison.
299	     *
300	     * @param lastName the last name of the owner being created
301	     * @param address the address of the owner being created
302	     * @throws DuplicateOwnerHouseholdException if another owner shares the household
303	     */
304	    private void requireUniqueHousehold(String lastName, String address) {
305	        String normalizedLastName = normalizeHousehold(lastName);
306	        String normalizedAddress = normalizeHousehold(address);
307	        boolean shared = this.clinicService.findAllOwners().stream()
308	            .anyMatch(existing -> normalizeHousehold(existing.getLastName()).equals(normalizedLastName)
309	                && normalizeHousehold(existing.getAddress()).equals(normalizedAddress));
310	        if (shared) {
311	            throw new DuplicateOwnerHouseholdException(lastName, address);
312	        }
313	    }
314	
315	    /**
316	     * Rejects an owner whose city already contains the maximum permitted number of owners
317	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
318	     * the same normalization used for the other owner household fields.
319	     *
320	     * @param city the city of the owner being created
321	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
322	     */
323	    private void requireCityHasCapacity(String city) {
324	        String normalizedCity = normalizeHousehold(city);
325	        long count = this.clinicService.findAllOwners().stream()
326	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
327	            .count();
328	        if (count >= CITY_CAPACITY) {
329	            throw new CityAtCapacityException(city);
330	        }
331	    }
332	
333	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
334	    @Override
335	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
336	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
337	        validateRequiredFields(ownerFieldsDto);
338	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
339	        requireUniqueTelephone(telephone);
340	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
341	            requireUniqueHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
342	        }
343	        requireCityHasCapacity(ownerFieldsDto.getCity());
344	        String email = normalizeEmail(ownerFieldsDto.getEmail());
345	        HttpHeaders headers = new HttpHeaders();
346	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
347	        owner.setTelephone(telephone);
348	        owner.setEmail(email);
349	        if (owner.getRegistrationDate() == null) {
350	            owner.setRegistrationDate(LocalDate.now());
351	        }
352	        this.clinicService.saveOwner(owner);
353	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
354	        headers.setLocation(UriComponentsBuilder.newInstance()
355	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
356	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
357	    }
358	
359	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
360	    @Override
361	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
362	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
363	        if (currentOwner == null) {
364	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
365	        }
366	        currentOwner.setAddress(ownerFieldsDto.getAddress());
367	        currentOwner.setCity(ownerFieldsDto.getCity());
368	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
369	        currentOwner.setLastName(ownerFieldsDto.getLastName());
370	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
371	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
372	        this.clinicService.saveOwner(currentOwner);
373	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
374	    }
375	
376	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
377	    @Transactional
378	    @Override
379	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
380	        Owner owner = this.clinicService.findOwnerById(ownerId);
381	        if (owner == null) {
382	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
383	        }
384	        this.clinicService.deleteOwner(owner);
385	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
386	    }
387	
388	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
389	    @Override
390	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
391	        Owner owner = this.clinicService.findOwnerById(ownerId);
392	        if (owner == null) {
393	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
394	        }
395	        HttpHeaders headers = new HttpHeaders();
396	        Pet pet = petMapper.toPet(petFieldsDto);
397	        owner.setId(ownerId);
398	        pet.setOwner(owner);
399	        pet.getType().setName(null);
400	        this.clinicService.savePet(pet);
401	        PetDto petDto = petMapper.toPetDto(pet);
402	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
403	            .buildAndExpand(pet.getId()).toUri());
404	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
405	    }
406	
407	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
408	    @Override
409	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
410	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
411	        if (currentOwner != null) {
412	            Pet currentPet = this.clinicService.findPetById(petId);
413	            if (currentPet != null) {
414	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
415	                currentPet.setName(petFieldsDto.getName());
416	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
417	                this.clinicService.savePet(currentPet);
418	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
419	            }
420	        }
421	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
422	    }
423	
424	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
425	    @Override
426	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
427	        HttpHeaders headers = new HttpHeaders();
428	        Visit visit = visitMapper.toVisit(visitFieldsDto);
429	        Pet pet = new Pet();
430	        pet.setId(petId);
431	        visit.setPet(pet);
432	        this.clinicService.saveVisit(visit);
433	        VisitDto visitDto = visitMapper.toVisitDto(visit);
434	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
435	            .buildAndExpand(visit.getId()).toUri());
436	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
437	    }
438	
439	
440	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
441	    @Override
442	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
443	        Owner owner = this.clinicService.findOwnerById(ownerId);
444	        if (owner != null) {
445	            Pet pet = owner.getPet(petId);
446	            if (pet != null) {
447	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
448	            }
449	        }
450	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
451	    }
